Flag Description <code>SA_RESTART</code> Automatically restart interrupted system calls <code>SA_SIGINFO</code> Use <code>sa_sigaction</code> instead of <code>sa_handler</code> <code>SA_NOCLDSTOP</code> Don't generate SIGCHLD when children stop <code>SA_NOCLDWAIT</code> Don't create zombies (auto-reap children) <code>SA_NODEFER</code> Don't block the signal during handler execution <code>SA_ONSTACK</code> Use alternate signal stack <code>SA_RESETHAND</code> Reset handler to SIG_DFL after delivery <pre><code>// SA_RESTART: Automatically restart interrupted calls
struct sigaction sa;
sa.sa_handler = handler;
sigemptyset(&amp;sa.sa_mask);
sa.sa_flags = SA_RESTART;  // read/write/pause will restart
sigaction(SIGALRM, &amp;sa, NULL);

// Without SA_RESTART:
// read() may return -1 with errno == EINTR
// With SA_RESTART:
// read() automatically restarts after signal handler returns
</code></pre>

Option Description <code>LOG_PID</code> Include PID in each message <code>LOG_NDELAY</code> Open connection immediately <code>LOG_CONS</code> Log to console if syslog unavailable <code>LOG_PERROR</code> Also log to stderr <pre><code>// Example: Daemon-specific logging
openlog("nginx", LOG_PID | LOG_NDELAY, LOG_LOCAL0);

// Log at different levels
syslog(LOG_INFO, "Worker %d started", getpid());
syslog(LOG_WARNING, "Connection limit approaching: %d/%d", current, max);
syslog(LOG_ERR, "Failed to open config: %s", strerror(errno));

// Set mask to only log warnings and above
setlogmask(LOG_UPTO(LOG_WARNING));
</code></pre>

Signal Action Description <code>SIGTERM</code> Graceful shutdown Stop accepting connections, finish work, exit <code>SIGINT</code> Graceful shutdown Same as SIGTERM <code>SIGHUP</code> Reload config Re-read configuration file <code>SIGUSR1</code> Reopen logs Close and reopen log files (for log rotation) <code>SIGUSR2</code> Custom Application-defined <code>SIGCHLD</code> Child status Reap child processes <pre><code>#include &lt;signal.h&gt;

static volatile sig_atomic_t reload_config = 0;
static volatile sig_atomic_t reopen_logs = 0;
static volatile sig_atomic_t shutdown_daemon = 0;

static void signal_handler(int sig)
{
    switch (sig) {
    case SIGHUP:
        reload_config = 1;
        break;
    case SIGUSR1:
        reopen_logs = 1;
        break;
    case SIGTERM:
    case SIGINT:
        shutdown_daemon = 1;
        break;
    }
}

// In main loop:
while (!shutdown_daemon) {
    if (reload_config) {
        reload_config = 0;
        load_config();
    }
    if (reopen_logs) {
        reopen_logs = 0;
        closelog();
        openlog("mydaemon", LOG_PID, LOG_DAEMON);
    }
    // ... daemon work ...
}
</code></pre>
